void RenderDevice::GetWindowSize(int32 *width, int32 *height)
{
    if (width)
        *width = videoSettings.fsWidth ? videoSettings.fsWidth : 1280;
    if (height)
        *height = videoSettings.fsHeight ? videoSettings.fsHeight : 720;
}

